        pxUV = 1.0 / T;
        float2 uv = amzScreenNorm();
        float tpp = T.x / max(screen.zw.x, 1.0);
        float P = max(amzp_polySample, 0.0);
        R = min(ceil((max(amzp_width, 0.0) + P * 1.5) * tpp + 3.0), 511.0);
        if (amzPass == 0) {
            float nS = 1024.0, nE = 1024.0;
            for (int i = 0; i < 1024; i++) {
                float x = float(i) - R;
                if (x > R) break;
                if (inShape(uv + float2(x * pxUV.x, 0.0))) { if (abs(x) < abs(nS)) nS = x; }
                else { if (abs(x) < abs(nE)) nE = x; }
            }
            amzOutput = float4(encS(nS), encS(nE));
            return;
        }
        if (amzPass == 1) {
            bool me = inShape(uv);
            float bm = 1e20;
            for (int i = 0; i < 1024; i++) {
                float y = float(i) - R;
                if (y > R) break;
                float4 s = amzTexture(1, uv + float2(0.0, y * pxUV.y));
                float dx = floor((me ? decS(s.ba) : decS(s.rg)) + 0.5);
                if (abs(dx) > R + 0.5) continue;
                bm = min(bm, dx * dx + y * y);
            }
            float dT = bm > 1e19 ? R + 1.0 : max(sqrt(bm) - 0.5, 0.0);
            amzOutput = float4(encS(me ? -dT : dT), 0.0, 1.0);
            return;
        }
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        sd0 = amzp_seed + (amzp_shuffle > 0.0 ? floor(time * amzp_shuffle) * 7.123 : 0.0);
        float2 pp = amzScreenNorm() * screen.zw / pxs;
        float4 src = amzTexture(0, uv);
        float dTrue = dfAt(uv) / tpp;
        float d = dTrue;
        float aa = 0.8 / tpp;
        float2 tri0 = float2(0.0), tri1 = float2(0.0), tri2 = float2(0.0);
        float2 id0 = float2(0.0), id1 = float2(0.0), id2 = float2(0.0);
        float2 cell = float2(0.0);
        float triId = 0.0;
        float2 grad = float2(0.0);
        bool poly = P >= 1.0;
        if (poly) {
            float2 q = pp / P;
            cell = floor(q);
            bool found = false;
            for (int j = -1; j <= 1; j++) {
                for (int i = -1; i <= 1; i++) {
                    if (found) continue;
                    float2 c = floor(q) + float2(float(i), float(j));
                    float2 a0 = jv(c), a1 = jv(c + float2(1.0, 0.0)), a2 = jv(c + float2(0.0, 1.0)), a3 = jv(c + float2(1.0, 1.0));
                    bool fl = h1(c, 11.0) > 0.5;
                    float2 A0 = a0, A1 = a1, A2 = fl ? a3 : a2;
                    float2 B0 = fl ? a0 : a1, B1 = a3, B2 = a2;
                    if (inTri(q, A0, A1, A2)) {
                        tri0 = A0; tri1 = A1; tri2 = A2; triId = 0.0; cell = c; found = true;
                        id0 = c; id1 = c + float2(1.0, 0.0); id2 = fl ? c + float2(1.0, 1.0) : c + float2(0.0, 1.0);
                    } else if (inTri(q, B0, B1, B2)) {
                        tri0 = B0; tri1 = B1; tri2 = B2; triId = 1.0; cell = c; found = true;
                        id0 = fl ? c : c + float2(1.0, 0.0); id1 = c + float2(1.0, 1.0); id2 = c + float2(0.0, 1.0);
                    }
                }
            }
            if (!found) { tri0 = jv(cell); tri1 = jv(cell + float2(1.0, 0.0)); tri2 = jv(cell + float2(0.0, 1.0)); id0 = cell; id1 = cell + float2(1.0, 0.0); id2 = cell + float2(0.0, 1.0); }
            float2 toUV = float2(pxs) / screen.zw;
            float2 u0 = uv + floor((tri0 * P * toUV - uv) / pxUV + 0.5) * pxUV;
            float2 u1 = uv + floor((tri1 * P * toUV - uv) / pxUV + 0.5) * pxUV;
            float2 u2 = uv + floor((tri2 * P * toUV - uv) / pxUV + 0.5) * pxUV;
            float2 v0 = u0 / toUV, v1 = u1 / toUV, v2 = u2 / toUV;
            float d0 = dfAt(u0) / tpp, d1 = dfAt(u1) / tpp, d2 = dfAt(u2) / tpp;
            float sk = clamp(amzp_spike, 0.0, 2.0) * max(amzp_width, 1.0) * 2.0;
            d0 += (0.4 - h1(id0, 21.0)) * sk;
            d1 += (0.4 - h1(id1, 21.0)) * sk;
            d2 += (0.4 - h1(id2, 21.0)) * sk;
            float2 e1 = v1 - v0, e2 = v2 - v0, e3 = pp - v0;
            float den = cr2(e1, e2);
            if (abs(den) > 1e-6) {
                float bv = cr2(e3, e2) / den;
                float bw = cr2(e1, e3) / den;
                d = d0 + (d1 - d0) * bv + (d2 - d0) * bw;
                grad = (float2(e2.y, -e2.x) * (d1 - d0) + float2(-e1.y, e1.x) * (d2 - d0)) / den;
                aa = max(length(grad), 0.05) * 0.8 / tpp;
            }
        }
        float w = max(amzp_width, 0.0);
        float lo, hi;
        if (int(amzp_position) == 0) { lo = 0.0; hi = w; }
        else if (int(amzp_position) == 1) { lo = -w * 0.5; hi = w * 0.5; }
        else { lo = -w; hi = 0.0; }
        float outer = 1.0 - smoothstep(hi - aa * 0.5, hi + aa * 0.5, d);
        float inner = smoothstep(lo - aa * 0.5, lo + aa * 0.5, d);
        float m;
        if (int(amzp_position) == 0) {
            m = (amzp_showLayer>0.5) ? outer : outer * (1.0 - src.a);
            m = max(m, (1.0 - smoothstep(w * 0.3 - 0.5 / tpp, w * 0.3 + 0.5 / tpp, dTrue)) * ((amzp_showLayer>0.5) ? 1.0 : 1.0 - src.a));
        } else if (int(amzp_position) == 1) m = inner * outer;
        else m = inner * src.a;
        if (w <= 0.0) m = 0.0;
        float3 sc = amzp_color.rgb;
        if (int(amzp_fillStyle) != 0 && poly) {
            float rnd = h1(cell * 2.0 + triId, 7.0);
            if (int(amzp_fillStyle) == 1) sc = mix(amzp_color.rgb, amzp_color2.rgb, rnd);
            else {
                float2 tc = (tri0 + tri1 + tri2) / 3.0 * P;
                float2 toUV = float2(pxs) / screen.zw;
                float2 gdir = length(grad) > 1e-4 ? normalize(grad) : float2(0.0);
                float dc = dfAt(uv + floor((tc * toUV - uv) / pxUV + 0.5) * pxUV) / tpp;
                float4 lc = alphaAt(tc * toUV - gdir * toUV * (dc + 2.0 / tpp)) > 0.3
                        ? amzTexture(0, tc * toUV - gdir * toUV * (dc + 2.0 / tpp)) : float4(0.0);
                sc = lc.a > 0.01 ? lc.rgb / lc.a : amzp_color.rgb;
            }
            sc *= 1.0 + (h1(cell * 3.0 + triId, 9.0) - 0.5) * 2.0 * clamp(amzp_facetShade, 0.0, 1.0);
            sc = clamp(sc, 0.0, 1.0);
        }
        float sa = clamp(m, 0.0, 1.0) * clamp(amzp_opacity, 0.0, 1.0);
        float4 stroke = float4(sc * sa, sa);
        float4 outc;
        if (!(amzp_showLayer>0.5)) outc = stroke;
        else if (int(amzp_position) == 2) outc = stroke + src * (1.0 - stroke.a);
        else outc = src + stroke * (1.0 - src.a);
        amzOutput = outc;
    }
    void amzRender() {
        if ((amzp_safeRender>0.5)) { amzOutput = amzTexture(0, amzScreenNorm()); return; }
        nmMain();
        if (!(amzp_overdrawOn>0.5) && amzPass >= 2) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
